"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

INCLUDE_DIRECTIVE = "@include"


def _read_lines(path):
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read().splitlines()


def _expand(lines, path, stack):
    """Return ``lines`` with ``@include`` directives recursively expanded.

    ``path`` is the file the lines came from; ``stack`` holds the real paths of
    the files currently being expanded, used to detect include cycles.
    """
    base_dir = os.path.dirname(os.path.abspath(path))
    expanded = []
    for raw in lines:
        parts = raw.strip().split(None, 1)
        if not parts or parts[0] != INCLUDE_DIRECTIVE:
            expanded.append(raw)
            continue
        if len(parts) < 2:
            raise ConfigError("{}: @include requires a path".format(path))
        target = os.path.join(base_dir, parts[1].strip())
        real = os.path.realpath(target)
        if real in stack:
            chain = " -> ".join(stack + [real])
            raise ConfigError("include cycle detected: {}".format(chain))
        try:
            child_lines = _read_lines(target)
        except FileNotFoundError:
            raise ConfigError(
                "{}: included file not found: {}".format(path, target)
            )
        except OSError as exc:
            raise ConfigError(
                "{}: cannot read included file {}: {}".format(path, target, exc)
            )
        expanded.extend(_expand(child_lines, target, stack + [real]))
    return expanded


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are replaced in place by the contents of the
    referenced file, resolved relative to the including file's directory.
    """
    lines = _read_lines(path)
    return parse_lines(_expand(lines, path, [os.path.realpath(path)]))


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
